<?php
declare(strict_types=1);
require __DIR__.'/test_weather_station.php';
sensor(49084,47887,'soilmoisture7','Bodenfeuchte (7) Rasen SüdWest Mitte',69,' %');
sensor(49084,10737,'soilmoisture8','Bodenfeuchte (8) Rasen Ost',71,' %');
sensor(49084,49076,'soilmoisture9','Bodenfeuchte (9) Beet unten Ersatz',55,' %');
sensor(49084,21340,'soilmoisture4','Bodenfeuchte (4) Eckbeet Ost',68,' %');
$catalog=IAHWeatherStation::merge($catalog);
$ask=static fn(string $q):array=>iah_rc_voice($q,[],$catalog);
$all=$ask('wie geht es meine bodenfeuchtsensoren');
check(str_starts_with($all['answer'],'Die Bodensensoren melden:')&&substr_count($all['answer'],'Die Bodensensoren')===1,'Sensor category is announced once');
foreach (['Hecke Ost 56 Prozent','Hecke Süd 50 Prozent','Rasen Ost 71 Prozent','Beet unten Ersatz 55 Prozent','Eckbeet Ost 68 Prozent'] as $expected) check(str_contains($all['answer'],$expected),'Every valid sensor, including readings beyond the old first four, is spoken: '.$expected);
check(!str_contains($all['answer'],'Froggit')&&!str_contains($all['answer'],'Bodenfeuchte (')&&!str_contains($all['answer'],'433Station'),'Technical station names and channel labels are not repeated in speech');
check(str_contains(json_encode($all['displayRows']),'Bodenfeuchte (7)'),'Full visual labels remain available independently of speech');
$grass=$ask('wie nass ist mein rasen');
check($grass['answerSource']==='house_status'&&count($grass['displayRows'])===2&&str_contains($grass['answer'],'Rasen Ost 71 Prozent'),'Exact logged question reaches the weather source and selects lawn sensors only');
check(str_contains($grass['answer'],'Luftfrost')&&!str_contains($grass['answer'],'Boden ist gefroren'),'Air frost is considered without claiming measured ground frost');
$report=$ask('Wie geht es meiner Wetterstation?');
check(str_starts_with($report['answer'],'Draußen herrscht Frost')&&str_contains($report['answer'],'Wind')&&str_contains($report['answer'],'regnet es nicht'),'Weather report leads with outdoor conditions, then wind and precipitation');
check(!str_contains($report['answer'],'Innensensor')&&!str_contains($report['answer'],'Froggit'),'Unasked indoor readings and technical names are omitted from weather speech');
check(str_contains($ask('Ist es kalt?')['answer'],'Frost'),'Short cold question explicitly answers outdoor conditions');
$GLOBALS['values'][44047]=15.0;
$wet=$ask('Braucht mein Rasen Wasser?');
check(str_contains($wet['answer'],'eher feucht')&&str_contains($wet['answer'],'keinen Hinweis auf Wasserbedarf'),'Warm-weather wet lawn uses sensor-specific indicative thresholds');
$GLOBALS['values'][10737]=15;
$dry=$ask('Muss ich den Rasen gießen?');
check(str_contains($dry['answer'],'Rasen Ost')&&str_contains($dry['answer'],'eher trocken')&&str_contains($dry['answer'],'Boden vor dem Gießen prüfen'),'Dry lawn gives a qualified, location-specific assessment');
$GLOBALS['values'][14904]=1.2;
check(str_contains($ask('Soll ich meinen Rasen bewässern?')['answer'],'Aktuell regnet es'),'Current rain is considered before watering advice');
$GLOBALS['values'][14904]=0.0;
$GLOBALS['vars'][600]['VariableUpdated']=time()-3600;
$stale=$ask('Braucht mein Rasen Wasser?');
check(str_contains($stale['answer'],'ohne aktuelle Bodenwerte nicht möglich')&&!str_contains($stale['answer'],'eher trocken'),'Stale low values never trigger a watering inference');
$GLOBALS['vars'][600]['VariableUpdated']=time();
$GLOBALS['profiles']['profile_44047']['Suffix']=' °F';$GLOBALS['values'][44047]=32.0;
check(str_contains($ask('Ist es draußen kalt?')['answer'],'Frost')&&str_contains($ask('Ist es draußen kalt?')['answer'],'Fahrenheit'),'Temperature assessment converts Fahrenheit rather than treating 32 F as heat');
$GLOBALS['profiles']['profile_44047']['Suffix']=' °C';$GLOBALS['values'][44047]=15.0;
check(str_contains($ask('Braucht mein Rasen Dünger?')['answer'],'Nährstoffen kann ich daraus nicht bestimmen'),'Moisture sensors never infer fertilizer needs');
check(IAHWeatherStation::query($catalog,'Wann wurde der Rasen zuletzt bewässert?')===null,'Irrigation event history remains with the existing irrigation engine');
foreach (['Braucht mein Rasen Wasser?','Muss ich den Rasen gießen?','Soll ich den Rasen bewässern?','Wie nass ist mein Rasen?','Bodensensoren'] as $q) check(iah_vir_classify(['text'=>$q,'intent'=>'HomeAgentFrageIntent'])['category']==='query','Care question is routed to the query backend: '.$q);

$editor=new WeatherEditorFixture($catalog);$refreshes=$editor->refreshes;
ob_start();$editor->SaveWeatherStationVariable('weather_station_49084',json_encode(['key'=>'var_10737','id'=>10737,'title'=>'Bodenfeuchte (8) Rasen Ost','speechName'=>'Ostrasen','dryThreshold'=>40,'wetThreshold'=>75,'enabled'=>true]));$notice=ob_get_clean();
check(str_contains($notice,'gespeichert')&&$editor->refreshes===$refreshes,'Saving a nested metric never replaces its parent list while the parent dialog is open');
$m=$editor->catalog['dataSources'][IAHWeatherStation::KEY]['devices']['station_49084']['variables']['var_10737'];
check($m['speechName']==='Ostrasen'&&$m['dryThreshold']===40.0&&$m['wetThreshold']===75.0,'Short spoken name and validated individual thresholds are persisted in EDIT');
check(IAHWeatherStation::merge($editor->catalog)===$editor->catalog,'Rescan preserves short names and configured thresholds');
$GLOBALS['values'][10737]=35;
$custom=IAHWeatherStation::query($editor->catalog,'Braucht mein Rasen Wasser?');
check(str_contains($custom['answer'],'Ostrasen 35 Prozent')&&str_contains($custom['answer'],'Ostrasen eher trocken'),'Custom speech and dry threshold are actually used in the report');
$before=$editor->catalog;
ob_start();$editor->SaveWeatherStationVariable('weather_station_49084',json_encode(['key'=>'var_10737','id'=>10737,'title'=>'Test','dryThreshold'=>80,'wetThreshold'=>20,'enabled'=>true]));$notice=ob_get_clean();
check($editor->catalog===$before&&str_contains($notice,'Richtwerte prüfen'),'Invalid thresholds are rejected before writing EDIT');
$columns=(new ReflectionMethod($rcc,'buildOverviewColumns'))->invoke($rcc);
$binding=array_values(array_filter($columns,static fn($c)=>($c['name']??'')==='WeatherVariables'))[0];
check($binding['edit']['type']==='List'&&$binding['add']===[],'Parent list has the documented native array binding for its nested weather list');
check(substr_count(file_get_contents(__DIR__.'/../RoomsCatalogConfigurator/module.php'),"['name'=>'WeatherVariables','visible'=>false,'add'=>[],'save'=>false,'edit'=>['type'=>'List']]")===2,'Both ordinary and pending-change device dialogs bind the nested list');
$form=json_decode($editor->GetWeatherStationEditForm('weather_station_49084'),true,512,JSON_THROW_ON_ERROR);
$list=array_values(array_filter($form,static fn($e)=>($e['name']??'')==='WeatherVariables'))[0];
check(in_array('metricTitle',array_column($list['columns'],'name'),true)&&!in_array('title',array_column($list['columns'],'name'),true),'Nested metric name is distinct from the outer device title');
echo "PASS logged lawn and soil questions, complete short names, prose weather report, units, guarded watering assessment and nested editor bindings\n";
